SELECT
    COUNT(1) AS totalEnterprise,
    SUM(IF(status = #{pending}, 1, 0)) AS cooperatingEnterprise,
    SUM(IF(status = #{ended}, 1, 0)) AS finishedEnterprise
FROM coop_enterprise
WHERE deleted = 0

     AND dept_id = #{deptId}


    AND coop_start_time >= #{startTime}


    AND coop_end_time  <=  #{endTime}

SELECT
    dept_id AS deptId,
    COUNT(1) AS coopCount
FROM coop_enterprise
WHERE deleted = 0

    AND dept_id = #{deptId}


    AND coop_start_time >= #{startTime}


    AND coop_end_time  <=  #{endTime}

GROUP BY dept_id

SELECT
DATE_FORMAT(coop_start_time, '%Y-%m-%d') AS date,
COUNT(1) AS count
FROM coop_enterprise
WHERE deleted = 0

    AND dept_id = #{deptId}


    AND coop_start_time >= #{startTime}


    AND coop_end_time  <=  #{endTime}

GROUP BY date
ORDER BY date

SELECT enterprise_type AS type, COUNT(1) AS coopCount FROM coop_enterprise WHERE deleted = 0
AND coop_start_time >= #{startTime}
AND coop_end_time <= #{endTime}
GROUP BY enterprise_type

SELECT dept_id AS deptId, COUNT(1) AS coopCount FROM coop_enterprise WHERE deleted = 0
AND coop_start_time >= #{startTime}
AND coop_end_time <= #{endTime}
GROUP BY dept_id
